dict.string:
.navbar {
	font-family: 'Hoefler Text', 'Times New Roman', serif;
	font-size: .6em;
	color: #463C3C;
	background-color: #FAF9F5;
	margin: 0px;
	line-height: 20px;
	text-transform: uppercase;
	font-weight: bold;
}

.navbar-bg {
	text-align: center;
	padding: 3px 0px 0px 0px;
}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0px;
}


li {
	list-style-type: none;
	display: inline;
	padding: 0px 10px 0px 10px;
}


li a {
	text-decoration: none;
	color: #463C3C;
}

li a:visited {
	text-decoration: none;
	color: #463C3C;
}

li a:hover{
 	color: #83785B;
	text-decoration: none;}


li.current-page a{	 color: #9C6810;
	text-decoration: none;}
